"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2237],{46719:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Opens a connection to the named datastore, falling back to\\n[DocumentDB:_tryReconnect] when the initial connect fails.","params":[{"name":"datastoreName","desc":"datastore to wrap","lua_type":"string"},{"name":"scope","desc":"optional datastore scope","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"DocumentDB"}],"function_type":"static","source":{"line":57,"path":"src/Server/Class/DB/DocumentDB.luau"}},{"name":"WipePlayerData","desc":"Permanently removes a user\'s entry. `RemoveAsync` is not throttled, so this\\nskips the request-budget wait.","params":[{"name":"userId","desc":"user whose entry to delete","lua_type":"number"}],"returns":[{"desc":"the removed value, or nil on failure","lua_type":"any"}],"function_type":"method","source":{"line":82,"path":"src/Server/Class/DB/DocumentDB.luau"}},{"name":"GetValue","desc":"Reads one user\'s value. Returns nil for an unset key and `false` when the\\nread itself failed.\\n\\nUnlike [DocumentDB:SetValue] this is not Studio-gated, so it reads live data\\nin Studio.\\n\\n:::warning Budget wait cannot terminate\\nThe request budget is sampled once into a local **before** the wait loop and\\nnever re-read inside it, so if the budget is below 3 on entry this spins\\nforever rather than for as long as it takes to recover. The equivalent loops\\nelsewhere in this file and in [OrderedDB] re-evaluate the budget each\\niteration.\\n:::","params":[{"name":"userId","desc":"user to read","lua_type":"number"}],"returns":[{"desc":"the value, nil when unset, false on read failure","lua_type":"any"}],"function_type":"method","source":{"line":121,"path":"src/Server/Class/DB/DocumentDB.luau"}},{"name":"SetValue","desc":"Writes a user\'s value immediately \u2014 no coalescing.\\n\\nGoes through `UpdateAsync` and returns the transform\'s sentinel nil when the\\nvalue is unchanged, so an identical rewrite is a no-op at the datastore\\nlevel. Nil values warn and are rejected.\\n\\nAlways a no-op returning true in Studio; see the class note.","params":[{"name":"userId","desc":"user to write","lua_type":"number"},{"name":"newValue","desc":"value to store; must not be nil","lua_type":"any"}],"returns":[{"desc":"whether the write succeeded","lua_type":"boolean"}],"function_type":"method","source":{"line":168,"path":"src/Server/Class/DB/DocumentDB.luau"}},{"name":"_tryReconnect","desc":"Retries the connection every 5 seconds until it succeeds, then returns the\\nlive store.\\n\\nUnlike [OrderedDB:_tryReconnect] this **yields the caller** \u2014 the wait is a\\nplain `task.wait` rather than a delayed thread \u2014 so [DocumentDB.new] blocks\\nuntil the datastore comes up.","params":[{"name":"dataStoreName","desc":"datastore to reconnect to","lua_type":"string"},{"name":"scope","desc":"optional datastore scope","lua_type":"string?"}],"returns":[{"desc":"the connected store","lua_type":"DataStore?"}],"function_type":"method","private":true,"source":{"line":228,"path":"src/Server/Class/DB/DocumentDB.luau"}},{"name":"_connect","desc":"Attempts one connection, warning and returning nil on failure rather than\\npropagating the error.","params":[{"name":"dataStoreName","desc":"datastore to open","lua_type":"string"},{"name":"scope","desc":"optional datastore scope","lua_type":"string?"}],"returns":[{"desc":"the store, or nil on failure","lua_type":"DataStore?"}],"function_type":"method","private":true,"source":{"line":256,"path":"src/Server/Class/DB/DocumentDB.luau"}}],"properties":[],"types":[],"name":"DocumentDB","desc":"Regular (non-ordered) datastore wrapper.\\n\\nAuthor: Zach Curtis (InfinityDesign)\\n\\nThe flat-key sibling of [OrderedDB], used where values are looked up by user\\nrather than ranked \u2014 [LeaderboardService]\'s `HasPlayedDB` is the main\\nconsumer. Same connect-with-retry and request-budget shape, but deliberately\\nsimpler: **no write coalescing**, so every [DocumentDB:SetValue] hits the\\ndatastore, and values may be any type rather than integers only.\\n\\nSupports an optional datastore `scope`, which [OrderedDB] does not.\\n\\n:::caution Studio writes are always discarded\\n[DocumentDB:SetValue] early-returns true whenever `RunService:IsStudio()`,\\nunconditionally \u2014 it does not consult `FeatureFlags.SaveInStudio` the way\\n[OrderedDB] does. Enabling that flag will not make this class persist in\\nStudio. Reads are unaffected and do hit the live datastore.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":27,"path":"src/Server/Class/DB/DocumentDB.luau"}}')}}]);